insert into categories (id, name, slug, description, cover_image, sort_order, is_active) values
  ('c0000000-0000-4000-8000-000000000001', 'Bridal', 'bridal', 'Heirloom bridal ensembles, worked by hand over months for the day you''ll remember forever.', '/dummy/noor-e-sahar/front.svg', 1, true),
  ('c0000000-0000-4000-8000-000000000002', 'Formal', 'formal', 'Evening wear for mehndis, valimas and dinners — quietly grand.', '/dummy/gulnaar/front.svg', 2, true),
  ('c0000000-0000-4000-8000-000000000003', 'Luxury Pret', 'luxury-pret', 'Ready-to-wear pieces with hand-finished detail, for days that deserve a little more.', '/dummy/sitara/front.svg', 3, true),
  ('c0000000-0000-4000-8000-000000000004', 'Festive', 'festive', 'Eid, Chaand Raat and family gatherings, dressed in colour and light.', '/dummy/zarrin/front.svg', 4, true),
  ('c0000000-0000-4000-8000-000000000005', 'Unstitched', 'unstitched', 'Hand-embroidered fabric, yours to tailor exactly as you like.', '/dummy/resham-rang/front.svg', 5, true)
